use camino::Utf8Path;
use indexmap::IndexMap;
use tree_sitter::Node;

use crate::config::TsStaticProfileConfig;
use crate::diagnostics::Diagnostic;
use crate::discover::MemorySourceFile;
use crate::error::{MemsrcError, Result};
use crate::ir::SourceRef;
use crate::parse::imports::resolve_relative_import;
use crate::parse::literal_eval::{ParsedExpr, ParsedExprKind};
use crate::parse::tree_sitter_ts;

#[derive(Debug, Clone)]
pub struct ParsedMemoryFile {
    pub source_file: MemorySourceFile,
    pub source_text: String,
    pub imports: Vec<ParsedImport>,
    pub consts: IndexMap<String, ParsedConst>,
    pub record_export: Option<ParsedRecordExport>,
    pub diagnostics: Vec<Diagnostic>,
}

#[derive(Debug, Clone)]
pub struct ParsedImport {
    pub local_name: String,
    pub imported_name: String,
    pub source_path: String,
    pub resolved_file: Option<String>,
}

#[derive(Debug, Clone)]
pub struct ParsedConst {
    pub name: String,
    pub exported: bool,
    pub expr: ParsedExpr,
    pub source: SourceRef,
}

#[derive(Debug, Clone)]
pub struct ParsedRecordExport {
    pub name: String,
    pub expr: ParsedExpr,
    pub source: SourceRef,
    pub id_symbol_name: Option<String>,
}

pub fn parse_file(
    root_dir: &Utf8Path,
    file: &MemorySourceFile,
    profile: &TsStaticProfileConfig,
) -> Result<ParsedMemoryFile> {
    let source_text = std::fs::read_to_string(&file.absolute_path)
        .map_err(|source| MemsrcError::io(&file.absolute_path, source))?;
    let tree = tree_sitter_ts::parse(&source_text)?;
    let mut diagnostics = Vec::new();
    let mut imports = Vec::new();
    let mut consts = IndexMap::new();
    let mut record_export = None;

    let root = tree.root_node();
    validate_disallowed_syntax(root, &source_text, file, profile, &mut diagnostics);

    let mut cursor = root.walk();
    for node in root.named_children(&mut cursor) {
        match node.kind() {
            "import_statement" => {
                imports.extend(parse_import(node, file, &source_text, &mut diagnostics)?);
            }
            "export_statement" => {
                if source_slice(node, &source_text)
                    .trim_start()
                    .starts_with("export default")
                {
                    diagnostics.push(diagnostic_for_node(
                        "PROFILE006",
                        "default exports are not allowed",
                        file,
                        node,
                    ));
                    continue;
                }
                if let Some(declaration) = find_child(node, "lexical_declaration") {
                    parse_lexical_declaration(
                        root_dir,
                        file,
                        &source_text,
                        declaration,
                        true,
                        &mut consts,
                        &mut record_export,
                        &mut diagnostics,
                    )?;
                } else {
                    diagnostics.push(diagnostic_for_node(
                        "PROFILE007",
                        "re-exports are not allowed",
                        file,
                        node,
                    ));
                }
            }
            "lexical_declaration" => {
                parse_lexical_declaration(
                    root_dir,
                    file,
                    &source_text,
                    node,
                    false,
                    &mut consts,
                    &mut record_export,
                    &mut diagnostics,
                )?;
            }
            _ => {}
        }
    }

    let file_kind = file
        .relative_path
        .file_name()
        .and_then(|name| name.split('.').nth_back(2))
        .map(str::to_owned);
    if profile.one_record_per_file && record_export.is_none() {
        diagnostics.push(Diagnostic::error(
            "PROFILE009",
            "one record export is required in each memory file",
            file.relative_path.as_str(),
            1,
            1,
        ));
    }
    if let (Some(record), Some(kind_suffix)) = (&record_export, file_kind) {
        if !record.name.ends_with(&kind_suffix) && !record.name.contains(&kind_suffix) {
            diagnostics.push(Diagnostic::warning(
                "RECORD010",
                format!("record export name should be stable snake_case for kind `{kind_suffix}`"),
                file.relative_path.as_str(),
                record.source.start_line,
                record.source.start_col,
            ));
        }
    }

    Ok(ParsedMemoryFile {
        source_file: file.clone(),
        source_text,
        imports,
        consts,
        record_export,
        diagnostics,
    })
}

fn parse_import(
    node: Node<'_>,
    file: &MemorySourceFile,
    source_text: &str,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<Vec<ParsedImport>> {
    let text = source_slice(node, source_text);
    let text = text.trim();
    if !text.contains(" from ") {
        diagnostics.push(diagnostic_for_node(
            "PROFILE007",
            "side-effect imports are not allowed",
            file,
            node,
        ));
        return Ok(Vec::new());
    }
    if text.contains("* as ") {
        diagnostics.push(diagnostic_for_node(
            "PROFILE007",
            "namespace imports are not allowed",
            file,
            node,
        ));
        return Ok(Vec::new());
    }
    let source_path = extract_import_path(text).ok_or_else(|| {
        MemsrcError::Message(format!(
            "failed to parse import source in {}",
            file.relative_path
        ))
    })?;
    if !source_path.starts_with("./") && !source_path.starts_with("../") {
        diagnostics.push(diagnostic_for_node(
            "PROFILE007",
            "imports must be relative",
            file,
            node,
        ));
    }

    let is_type_only = text.starts_with("import type ");
    let names = extract_braced_names(text);
    if names.is_empty() && !is_type_only {
        diagnostics.push(diagnostic_for_node(
            "PROFILE007",
            "runtime imports must use named imports",
            file,
            node,
        ));
    }
    let resolved_file = resolve_relative_import(&file.relative_path, &source_path);
    Ok(names
        .into_iter()
        .map(|(imported_name, local_name)| ParsedImport {
            local_name,
            imported_name,
            source_path: source_path.clone(),
            resolved_file: resolved_file.clone(),
        })
        .collect())
}

