use std::cmp::Ordering;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Diagnostic {
    pub code: String,
    pub severity: Severity,
    pub message: String,
    pub file: String,
    pub line: usize,
    pub col: usize,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub end_line: Option<usize>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub end_col: Option<usize>,
}

impl Diagnostic {
    pub fn error(
        code: impl Into<String>,
        message: impl Into<String>,
        file: impl Into<String>,
        line: usize,
        col: usize,
    ) -> Self {
        Self {
            code: code.into(),
            severity: Severity::Error,
            message: message.into(),
            file: file.into(),
            line,
            col,
            end_line: None,
            end_col: None,
        }
    }

    pub fn warning(
        code: impl Into<String>,
        message: impl Into<String>,
        file: impl Into<String>,
        line: usize,
        col: usize,
    ) -> Self {
        Self {
            code: code.into(),
            severity: Severity::Warning,
            message: message.into(),
            file: file.into(),
            line,
            col,
            end_line: None,
            end_col: None,
        }
    }

    pub fn with_end(mut self, end_line: usize, end_col: usize) -> Self {
        self.end_line = Some(end_line);
        self.end_col = Some(end_col);
        self
    }
}

impl Eq for Diagnostic {}

impl PartialEq for Diagnostic {
    fn eq(&self, other: &Self) -> bool {
        self.code == other.code
            && self.file == other.file
            && self.line == other.line
            && self.col == other.col
            && self.message == other.message
    }
}

impl PartialOrd for Diagnostic {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Diagnostic {
    fn cmp(&self, other: &Self) -> Ordering {
        (
            &self.file,
            self.line,
            self.col,
            &self.code,
            &self.message,
            self.severity,
        )
            .cmp(&(
                &other.file,
                other.line,
                other.col,
                &other.code,
                &other.message,
                other.severity,
            ))
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ValidationStats {
    pub files: usize,
    pub records: usize,
    pub claims: usize,
    pub edges: usize,
    pub errors: usize,
    pub warnings: usize,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ValidationReport {
    pub diagnostics: Vec<Diagnostic>,
    pub stats: ValidationStats,
}

impl ValidationReport {
    pub fn push(&mut self, diagnostic: Diagnostic) {
        match diagnostic.severity {
            Severity::Error => self.stats.errors += 1,
            Severity::Warning => self.stats.warnings += 1,
        }
        self.diagnostics.push(diagnostic);
    }

    pub fn extend<I>(&mut self, diagnostics: I)
    where
        I: IntoIterator<Item = Diagnostic>,
    {
        for diagnostic in diagnostics {
            self.push(diagnostic);
        }
    }

    pub fn has_errors(&self) -> bool {
        self.stats.errors > 0
    }

    pub fn render_human(&self) -> String {
        let mut lines = Vec::new();
        for diagnostic in &self.diagnostics {
            lines.push(format!(
                "{}:{}:{} {} {}",
                diagnostic.file,
                diagnostic.line,
                diagnostic.col,
                diagnostic.code,
                diagnostic.message
            ));
        }
        lines.push(format!(
            "files: {} records: {} claims: {} edges: {} errors: {} warnings: {}",
            self.stats.files,
            self.stats.records,
            self.stats.claims,
            self.stats.edges,
            self.stats.errors,
            self.stats.warnings
        ));
        lines.join("\n")
    }
}

