        };
        let name = source_slice(name_node, source_text).to_owned();
        let expr = parse_expr(file, source_text, value_node, diagnostics)?;
        let source = source_ref(file, declarator, name.clone());
        if exported && matches!(expr.kind, ParsedExprKind::Object(_)) {
            let has_as_const = source_slice(value_node, source_text).contains("as const");
            let has_satisfies =
                source_slice(value_node, source_text).contains("satisfies MemoryRecord<");
            if !has_as_const || !has_satisfies {
                diagnostics.push(diagnostic_for_node(
                    "PROFILE008",
                    "record export must use `as const satisfies MemoryRecord<...>`",
                    file,
                    declarator,
                ));
            }
            if record_export.is_some() {
                diagnostics.push(diagnostic_for_node(
                    "PROFILE009",
                    "only one record export is allowed per file",
                    file,
                    declarator,
