}

fn infer_record_id_symbol(expr: &ParsedExpr) -> Option<String> {
    let ParsedExprKind::Object(fields) = &expr.kind else {
        return None;
    };
    fields.iter().find_map(|(key, value)| {
        if key == "id" {
            if let ParsedExprKind::Identifier(name) = &value.kind {
                return Some(name.clone());
            }
        }
        None
    })
}

fn parse_expr(
    file: &MemorySourceFile,
    source_text: &str,
    node: Node<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<ParsedExpr> {
    let source = source_ref(file, node, String::new());
    let kind = match node.kind() {
        "string" => ParsedExprKind::String(parse_js_string(source_slice(node, source_text))),
        "number" => {
            ParsedExprKind::Number(source_slice(node, source_text).parse().map_err(|error| {
                MemsrcError::Message(format!("invalid numeric literal: {error}"))
            })?)
        }
        "true" => ParsedExprKind::Bool(true),
        "false" => ParsedExprKind::Bool(false),
        "null" => ParsedExprKind::Null,
        "identifier" => ParsedExprKind::Identifier(source_slice(node, source_text).to_owned()),
        "array" => {
            let mut cursor = node.walk();
            let mut items = Vec::new();
            for child in node.named_children(&mut cursor) {
                items.push(parse_expr(file, source_text, child, diagnostics)?);
            }
            ParsedExprKind::Array(items)
        }
        "object" => {
            let mut cursor = node.walk();
            let mut fields = Vec::new();
            for child in node.named_children(&mut cursor) {
                match child.kind() {
                    "pair" => {
                        let key_node = child.child_by_field_name("key").ok_or_else(|| {
                            MemsrcError::Message("object pair missing key".into())
                        })?;
                        let value_node = child.child_by_field_name("value").ok_or_else(|| {
                            MemsrcError::Message("object pair missing value".into())
                        })?;
                        let key = match key_node.kind() {
                            "property_identifier" | "identifier" => {
                                source_slice(key_node, source_text).to_owned()
                            }
                            "string" => parse_js_string(source_slice(key_node, source_text)),
                            "computed_property_name" => {
                                diagnostics.push(diagnostic_for_node(
                                    "PROFILE004",
                                    "computed properties are not allowed",
                                    file,
                                    child,
                                ));
                                continue;
                            }
                            _ => {
                                diagnostics.push(diagnostic_for_node(
                                    "PROFILE010",
                                    "object keys must be literal",
                                    file,
                                    child,
                                ));
                                continue;
                            }
                        };
                        fields.push((key, parse_expr(file, source_text, value_node, diagnostics)?));
                    }
                    "spread_element" => diagnostics.push(diagnostic_for_node(
                        "PROFILE005",
                        "object spreads are not allowed",
                        file,
                        child,
                    )),
                    _ => diagnostics.push(diagnostic_for_node(
                        "PROFILE010",
                        "unsupported object member",
                        file,
                        child,
                    )),
                }
            }
            ParsedExprKind::Object(fields)
        }
        "parenthesized_expression" | "as_expression" | "satisfies_expression" => {
            let inner = first_named_child(node).ok_or_else(|| {
                MemsrcError::Message(format!("missing inner expression for {}", node.kind()))
            })?;
            return parse_expr(file, source_text, inner, diagnostics);
        }
        "template_string" => {
            if source_slice(node, source_text).contains("${") {
                diagnostics.push(diagnostic_for_node(
                    "PROFILE010",
                    "template interpolation is not allowed",
                    file,
                    node,
                ));
            }
            ParsedExprKind::String(strip_template_quotes(source_slice(node, source_text)))
        }
        _ => {
            diagnostics.push(diagnostic_for_node(
                "PROFILE010",
                format!("unsupported static expression `{}`", node.kind()),
                file,
                node,
            ));
            ParsedExprKind::Null
        }
    };
    Ok(ParsedExpr { source, kind })
}

fn validate_disallowed_syntax(
    node: Node<'_>,
    source_text: &str,
    file: &MemorySourceFile,
    profile: &TsStaticProfileConfig,
    diagnostics: &mut Vec<Diagnostic>,
) {
    recurse_disallowed(node, source_text, file, profile, diagnostics);
}

fn recurse_disallowed<'a>(
    node: Node<'a>,
    source_text: &str,
    file: &MemorySourceFile,
    profile: &TsStaticProfileConfig,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let code = match node.kind() {
        "function_declaration"
        | "function_expression"
        | "arrow_function"
        | "generator_function_declaration" => {
            Some(("PROFILE002", "executable declarations are not allowed"))
        }
        "class_declaration" | "class" | "class_body" | "method_definition" | "enum_declaration" => {
            Some(("PROFILE002", "classes and enums are not allowed"))
        }
        "call_expression" => Some(("PROFILE003", "call expressions are not allowed")),
        "new_expression" | "await_expression" | "yield_expression" => {
            Some(("PROFILE002", "runtime expressions are not allowed"))
        }
        "assignment_expression" | "update_expression" => {
            Some(("PROFILE002", "mutation is not allowed"))
        }
        "conditional_expression" | "binary_expression" => {
            Some(("PROFILE010", "computed expressions are not allowed"))
        }
        "spread_element" => Some(("PROFILE005", "spread syntax is not allowed")),
        kind if kind.starts_with("jsx_") => Some(("PROFILE002", "JSX is not allowed")),
        _ => None,
    };

    if let Some((code, message)) = code {
        diagnostics.push(diagnostic_for_node(code, message, file, node));
    }
    if node.kind() == "import_statement"
        && !profile.allow_runtime_imports
        && source_slice(node, source_text)
            .trim_start()
            .starts_with("import ")
        && !source_slice(node, source_text)
            .trim_start()
            .starts_with("import type ")
        && !source_slice(node, source_text).contains('{')
    {
        diagnostics.push(diagnostic_for_node(
            "PROFILE007",
            "runtime imports are not allowed",
            file,
            node,
        ));
    }

    let mut cursor = node.walk();
    for child in node.named_children(&mut cursor) {
        recurse_disallowed(child, source_text, file, profile, diagnostics);
    }
}

fn source_slice<'a>(node: Node<'_>, source_text: &'a str) -> &'a str {
    &source_text[node.byte_range()]
}

fn parse_js_string(raw: &str) -> String {
    let trimmed = raw.trim_matches('"').trim_matches('\'');
    trimmed.replace("\\n", "\n").replace("\\\"", "\"")
}

fn strip_template_quotes(raw: &str) -> String {
    raw.trim_matches('`').to_owned()
}

fn source_ref(file: &MemorySourceFile, node: Node<'_>, export_name: String) -> SourceRef {
    let start = node.start_position();
    let end = node.end_position();
    SourceRef {
        file: file.relative_path.as_str().to_owned(),
        export_name,
        start_line: start.row + 1,
        start_col: start.column + 1,
        end_line: end.row + 1,
        end_col: end.column + 1,
        start_byte: node.start_byte(),
        end_byte: node.end_byte(),
    }
}

