pub fn parse_files(
    root_dir: &Utf8Path,
    files: &[MemorySourceFile],
    profile: &TsStaticProfileConfig,
) -> Result<Vec<ParsedMemoryFile>> {
    let mut parsed = Vec::new();
    for file in files {
        parsed.push(ts_profile::parse_file(root_dir, file, profile)?);
    }
    Ok(parsed)
}

pub fn extract_records(
    _root_dir: &Utf8Path,
    package: &MemoryPackage,
    files: Vec<MemorySourceFile>,
    parsed_files: Vec<ParsedMemoryFile>,
) -> Result<ExtractionSet> {
    let mut diagnostics = Vec::new();
    let extractor = Extractor::new(package, &parsed_files);
    let mut records = Vec::new();

    for file in &parsed_files {
        diagnostics.extend(file.diagnostics.iter().cloned());
        if let Some(record) = extractor.extract_record(file, &mut diagnostics)? {
            records.push(record);
        }
    }

    records.sort_by(|left, right| {
        left.id
            .cmp(&right.id)
            .then(left.source.file.cmp(&right.source.file))
    });
    diagnostics.sort();

    Ok(ExtractionSet {
        files,
        parsed_files,
        records,
        diagnostics,
    })
}

struct Extractor<'a> {
    package: &'a MemoryPackage,
    files_by_path: BTreeMap<&'a str, &'a ParsedMemoryFile>,
}

impl<'a> Extractor<'a> {
    fn new(package: &'a MemoryPackage, parsed_files: &'a [ParsedMemoryFile]) -> Self {
        let files_by_path = parsed_files
            .iter()
            .map(|file| (file.source_file.relative_path.as_str(), file))
            .collect();
        Self {
            package,
            files_by_path,
        }
    }

    fn extract_record(
        &self,
        file: &ParsedMemoryFile,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Result<Option<ExtractedMemoryRecord>> {
        let Some(record_export) = &file.record_export else {
            return Ok(None);
        };
        let mut stack = BTreeSet::new();
        let value = self.resolve_expr(file, &record_export.expr, &mut stack, diagnostics)?;
        let object = match &value.value {
            EvaluatedValue::Object(object) => object,
            _ => {
                diagnostics.push(Diagnostic::error(
                    "PROFILE010",
                    "record export did not evaluate to an object",
                    file.source_file.relative_path.as_str(),
                    record_export.source.start_line,
                    record_export.source.start_col,
                ));
                return Ok(None);
            }
        };
        let record_symbol = record_export.name.clone();
        let id_symbol = record_export
            .id_symbol_name
            .as_ref()
            .filter(|name| {
                file.consts
                    .get(*name)
                    .map(|item| item.exported)
                    .unwrap_or(false)
            })
            .cloned();

        let record = normalize_record(
            file,
            self.package.profile.profile_version.clone(),
            object,
            &value.source,
            record_symbol,
            id_symbol,
            &file.imports,
            &file.consts,
            diagnostics,
        )?;
        Ok(record)
    }

    fn resolve_expr(
        &self,
        file: &ParsedMemoryFile,
        expr: &ParsedExpr,
        stack: &mut BTreeSet<(String, String)>,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Result<SourcedValue> {
        let value = match &expr.kind {
            literal_eval::ParsedExprKind::String(value) => EvaluatedValue::String(value.clone()),
            literal_eval::ParsedExprKind::Number(value) => EvaluatedValue::Number(*value),
            literal_eval::ParsedExprKind::Bool(value) => EvaluatedValue::Bool(*value),
            literal_eval::ParsedExprKind::Null => EvaluatedValue::Null,
            literal_eval::ParsedExprKind::Array(items) => {
                let mut array = Vec::new();
                for item in items {
                    array.push(self.resolve_expr(file, item, stack, diagnostics)?);
                }
                EvaluatedValue::Array(array)
            }
            literal_eval::ParsedExprKind::Object(properties) => {
                let mut object = BTreeMap::new();
                for (key, value) in properties {
                    object.insert(
                        key.clone(),
                        self.resolve_expr(file, value, stack, diagnostics)?,
                    );
                }
                EvaluatedValue::Object(object)
            }
            literal_eval::ParsedExprKind::Identifier(identifier) => {
                if let Some(value) =
                    self.resolve_identifier(file, identifier, stack, diagnostics)?
                {
                    return Ok(value.mark_identifier());
                }
                diagnostics.push(Diagnostic::error(
                    "PROFILE010",
                    format!("identifier `{identifier}` could not be resolved"),
                    expr.source.file.clone(),
                    expr.source.start_line,
                    expr.source.start_col,
                ));
                EvaluatedValue::Null
            }
        };
        Ok(SourcedValue::new(expr.source.clone(), value))
    }

    fn resolve_identifier(
        &self,
        file: &ParsedMemoryFile,
        identifier: &str,
        stack: &mut BTreeSet<(String, String)>,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Result<Option<SourcedValue>> {
        if let Some(parsed_const) = file.consts.get(identifier) {
            return self
                .resolve_const(file, parsed_const, stack, diagnostics)
                .map(Some);
        }

        if let Some(import_ref) = file
            .imports
            .iter()
            .find(|item| item.local_name == identifier)
        {
            if let Some(resolved_file) = &import_ref.resolved_file {
                if let Some(parsed_file) = self.files_by_path.get(resolved_file.as_str()) {
                    if let Some(parsed_const) = parsed_file.consts.get(&import_ref.imported_name) {
                        return self
                            .resolve_const(parsed_file, parsed_const, stack, diagnostics)
                            .map(Some);
                    }
                }
            }
        }

        Ok(None)
    }

    fn resolve_const(
        &self,
        file: &ParsedMemoryFile,
        parsed_const: &ParsedConst,
        stack: &mut BTreeSet<(String, String)>,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Result<SourcedValue> {
        let key = (
            file.source_file.relative_path.as_str().to_owned(),
            parsed_const.name.clone(),
        );
        if !stack.insert(key.clone()) {
            diagnostics.push(Diagnostic::error(
                "PROFILE010",
                format!("cyclic const resolution for `{}`", parsed_const.name),
                file.source_file.relative_path.as_str(),
                parsed_const.source.start_line,
                parsed_const.source.start_col,
            ));
            return Ok(SourcedValue::new(
                parsed_const.source.clone(),
                EvaluatedValue::Null,
            ));
        }

        let value = self.resolve_expr(file, &parsed_const.expr, stack, diagnostics)?;
        stack.remove(&key);
        Ok(value)
    }
}

