pub fn validate_extraction(
    package: &MemoryPackage,
    extraction: &ExtractionSet,
    options: ValidationOptions,
) -> Result<ValidationReport> {
    let mut report = ValidationReport {
        diagnostics: extraction.diagnostics.clone(),
        stats: ValidationStats {
            files: extraction.files.len(),
            records: extraction.records.len(),
            claims: extraction
                .records
                .iter()
                .map(|record| record.claims.len())
                .sum(),
            edges: extraction
                .records
                .iter()
                .map(|record| record.edges.len())
                .sum(),
            errors: extraction
                .diagnostics
                .iter()
                .filter(|item| item.severity == crate::diagnostics::Severity::Error)
                .count(),
            warnings: extraction
                .diagnostics
                .iter()
                .filter(|item| item.severity == crate::diagnostics::Severity::Warning)
                .count(),
        },
    };

    let mut ids = BTreeMap::new();
    for record in &extraction.records {
        if let Some(previous) = ids.insert(record.id.clone(), record.source.file.clone()) {
            report.push(Diagnostic::error(
                "RECORD003",
                format!("duplicate id `{}` also found in {}", record.id, previous),
                record.source.file.clone(),
                record.source.start_line,
                record.source.start_col,
            ));
        }
    }

    let all_ids = ids.keys().cloned().collect::<BTreeSet<_>>();
    for record in &extraction.records {
        validate_record(record, package, &all_ids, &mut report, options.strict);
    }

    report.diagnostics.sort();
    Ok(report)
}

