        id_symbol,
        record_symbol,
        imports: imports
            .iter()
            .map(|item| ImportRef {
                local_name: item.local_name.clone(),
                imported_name: item.imported_name.clone(),
                source_path: item.source_path.clone(),
                resolved_file: item.resolved_file.clone(),
            })
            .collect(),
        local_consts,
    };

    Ok(Some(ExtractedMemoryRecord {
        schema_version,
        id,
        kind,
        title,
        status,
        summary,
        body,
        claims,
        edges,
        evidence,
        lifecycle,
        retrieval,
        governance,
        source: source.clone(),
        symbols,
        raw: RawExtractionInfo {
            source_hash,
            profile_version,
        },
    }))
}

fn required_string(
    file: &ParsedMemoryFile,
    object: &BTreeMap<String, SourcedValue>,
    key: &str,
    code: &str,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<String> {
    let Some(value) = object.get(key) else {
        diagnostics.push(Diagnostic::error(
            code,
            format!("`{key}` is required"),
            file.source_file.relative_path.as_str(),
            file.record_export
                .as_ref()
                .map(|item| item.source.start_line)
                .unwrap_or(1),
            file.record_export
                .as_ref()
                .map(|item| item.source.start_col)
                .unwrap_or(1),
        ));
        return Ok(String::new());
    };
    as_string(value, key)
}

fn optional_string(object: &BTreeMap<String, SourcedValue>, key: &str) -> Result<Option<String>> {
    object
        .get(key)
        .map(|value| as_string(value, key))
        .transpose()
}

fn required_enum<T>(
    file: &ParsedMemoryFile,
    object: &BTreeMap<String, SourcedValue>,
    key: &str,
    code: &str,
    diagnostics: &mut Vec<Diagnostic>,
    parser: fn(&str) -> Option<T>,
) -> Result<T> {
    let raw = required_string(file, object, key, code, diagnostics)?;
    parser(&raw).ok_or_else(|| MemsrcError::Message(format!("invalid `{key}` value `{raw}`")))
}

fn parse_claims(
    file: &ParsedMemoryFile,
    value: Option<&SourcedValue>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<Vec<MemoryClaim>> {
    let Some(value) = value else {
        return Ok(Vec::new());
    };
    let array = as_array(value, "claims")?;
    let mut claims = Vec::new();
    for claim in array {
        let object = as_object(claim, "claim")?;
        claims.push(MemoryClaim {
            id: required_value_string(file, object, "id", "CLAIM001", diagnostics, claim)?,
            text: required_value_string(file, object, "text", "CLAIM002", diagnostics, claim)?,
            stance: required_value_enum(
                file,
                object,
                "stance",
                "CLAIM005",
                diagnostics,
                claim,
                parse_claim_stance,
            )?,
            confidence: optional_number(object, "confidence")?.unwrap_or_default() as f32,
            basis: required_value_enum(
                file,
                object,
                "basis",
                "CLAIM004",
                diagnostics,
                claim,
                parse_claim_basis,
            )?,
            evidence_refs: optional_string_vec(object, "evidence_refs")?,
            qualifiers: optional_string_vec(object, "qualifiers")?,
            valid_from: optional_string(object, "valid_from")?,
            valid_until: optional_string(object, "valid_until")?,
        });
    }
    Ok(claims)
}

fn parse_evidence(
    file: &ParsedMemoryFile,
    value: Option<&SourcedValue>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<Vec<EvidenceRef>> {
    let Some(value) = value else {
        return Ok(Vec::new());
    };
    let array = as_array(value, "evidence")?;
    let mut evidence = Vec::new();
    for item in array {
        let object = as_object(item, "evidence")?;
        evidence.push(EvidenceRef {
            id: required_value_string(file, object, "id", "CLAIM006", diagnostics, item)?,
            kind: required_value_enum(
                file,
                object,
                "kind",
                "CLAIM006",
                diagnostics,
                item,
                parse_evidence_kind,
            )?,
            title: optional_string(object, "title")?,
            locator: required_value_string(file, object, "locator", "CLAIM006", diagnostics, item)?,
            captured_at: optional_string(object, "captured_at")?,
            quote: optional_string(object, "quote")?,
            hash: optional_string(object, "hash")?,
        });
    }
    Ok(evidence)
}

fn parse_edges(
    file: &ParsedMemoryFile,
    value: Option<&SourcedValue>,
    from: &str,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<Vec<MemoryEdge>> {
    let Some(value) = value else {
        return Ok(Vec::new());
    };
    let array = as_array(value, "edges")?;
    let mut edges = Vec::new();
    for item in array {
        let object = as_object(item, "edge")?;
        edges.push(MemoryEdge {
            from: from.to_owned(),
            rel: required_value_enum(
                file,
                object,
                "rel",
                "EDGE001",
                diagnostics,
                item,
                parse_edge_rel,
            )?,
            to: required_value_string(file, object, "to", "EDGE002", diagnostics, item)?,
            confidence: optional_number(object, "confidence")?.map(|value| value as f32),
            strength: optional_number(object, "strength")?.map(|value| value as f32),
            note: optional_string(object, "note")?,
            evidence_refs: optional_string_vec(object, "evidence_refs")?,
            source: item.source.clone(),
            symbolic_target: object
                .get("to")
                .map(|value| value.from_identifier)
                .unwrap_or(false),
        });
    }
    Ok(edges)
}

fn parse_lifecycle(
    file: &ParsedMemoryFile,
    value: Option<&SourcedValue>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<MemoryLifecycle> {
    let Some(value) = value else {
        diagnostics.push(Diagnostic::error(
            "LIFE001",
            "`lifecycle` is required",
            file.source_file.relative_path.as_str(),
            file.record_export
                .as_ref()
                .map(|item| item.source.start_line)
                .unwrap_or(1),
            file.record_export
                .as_ref()
                .map(|item| item.source.start_col)
                .unwrap_or(1),
        ));
        return Ok(MemoryLifecycle {
            created_at: String::new(),
            updated_at: None,
            valid_from: None,
            valid_until: None,
            supersedes: Vec::new(),
            superseded_by: Vec::new(),
            retraction: None,
        });
    };
    let object = as_object(value, "lifecycle")?;
    let retraction = match object.get("retraction") {
        Some(item) => {
            let object = as_object(item, "retraction")?;
            Some(Retraction {
                retracted_at: required_value_string(
                    file,
                    object,
                    "retracted_at",
                    "LIFE005",
                    diagnostics,
                    item,
                )?,
                reason: required_value_string(
                    file,
                    object,
                    "reason",
                    "LIFE005",
                    diagnostics,
                    item,
                )?,
                replaced_by: optional_string(object, "replaced_by")?,
            })
        }
        None => None,
    };
    Ok(MemoryLifecycle {
        created_at: required_value_string(
            file,
            object,
            "created_at",
            "LIFE001",
            diagnostics,
            value,
        )?,
        updated_at: optional_string(object, "updated_at")?,
        valid_from: optional_string(object, "valid_from")?,
        valid_until: optional_string(object, "valid_until")?,
        supersedes: optional_string_vec(object, "supersedes")?,
        superseded_by: optional_string_vec(object, "superseded_by")?,
        retraction,
    })
}

