#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SymbolIndex {
    pub schema_version: String,
    pub symbols: Vec<SymbolEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SymbolEntry {
    pub symbol: String,
    pub value: String,
    pub kind: String,
    pub file: String,
    pub line: usize,
}

pub fn build_symbols(extraction: &ExtractionSet) -> Result<SymbolIndex> {
    let mut symbols = Vec::new();
    for record in &extraction.records {
        if let Some(symbol) = &record.symbols.id_symbol {
            symbols.push(SymbolEntry {
                symbol: symbol.clone(),
                value: record.id.clone(),
                kind: "id_const".into(),
                file: record.source.file.clone(),
                line: record.source.start_line,
            });
        }
        symbols.push(SymbolEntry {
            symbol: record.symbols.record_symbol.clone(),
            value: record.id.clone(),
            kind: "record_export".into(),
            file: record.source.file.clone(),
            line: record.source.start_line,
        });
    }
    symbols.sort_by(|left, right| {
        left.symbol
            .cmp(&right.symbol)
            .then(left.file.cmp(&right.file))
    });
    Ok(SymbolIndex {
        schema_version: "memsrc.symbols.v0.1".into(),
        symbols,
    })
}

