#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ComparisonReport {
    pub schema_version: String,
    pub source_record_count: usize,
    pub baseline_record_count: usize,
    pub matching_ids: Vec<String>,
    pub missing_in_source: Vec<String>,
    pub missing_in_baseline: Vec<String>,
}

pub fn compare_records(
    extraction: &ExtractionSet,
    baseline: &[crate::ir::ExtractedMemoryRecord],
) -> Result<ComparisonReport> {
    let source_ids = extraction
        .records
        .iter()
        .map(|record| record.id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let baseline_ids = baseline
        .iter()
        .map(|record| record.id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let matching_ids = source_ids
        .intersection(&baseline_ids)
        .cloned()
        .collect::<Vec<_>>();
    let missing_in_source = baseline_ids
        .difference(&source_ids)
        .cloned()
        .collect::<Vec<_>>();
    let missing_in_baseline = source_ids
        .difference(&baseline_ids)
        .cloned()
        .collect::<Vec<_>>();
    Ok(ComparisonReport {
        schema_version: "memsrc.compare.v0.1".into(),
        source_record_count: extraction.records.len(),
        baseline_record_count: baseline.len(),
        matching_ids,
        missing_in_source,
        missing_in_baseline,
    })
}

