fn init(dir: &Utf8Path) -> Result<()> {
    std::fs::create_dir_all(dir.join("memory/schema"))
        .map_err(|source| MemsrcError::io(dir, source))?;
    std::fs::create_dir_all(dir.join("memory/entities"))
        .map_err(|source| MemsrcError::io(dir, source))?;
    std::fs::create_dir_all(dir.join("memory/concepts"))
        .map_err(|source| MemsrcError::io(dir, source))?;
    std::fs::create_dir_all(dir.join("memory/decisions"))
        .map_err(|source| MemsrcError::io(dir, source))?;
    write_if_missing(
        &dir.join("memory.source.json"),
        include_str!("../templates/memory.source.json"),
    )?;
    write_if_missing(
        &dir.join("memory/schema/memory.schema.ts"),
        include_str!("../templates/memory.schema.ts"),
    )?;
    write_if_missing(&dir.join("memory/entities/.gitkeep"), "")?;
    write_if_missing(&dir.join("memory/concepts/.gitkeep"), "")?;
    write_if_missing(&dir.join("memory/decisions/.gitkeep"), "")?;
    println!("initialized {}", dir);
    Ok(())
}

fn check(package: &Utf8Path) -> Result<()> {
    let project = MemSourceProject::load(package, LoadOptions)?;
    let extraction = project.extract(ExtractOptions)?;
    let report = project.validate(&extraction, ValidationOptions::strict())?;
    println!("memsrc check");
    print_stats(&report.stats);
    if report.has_errors() {
        eprintln!("{}", report.render_human());
        std::process::exit(1);
    }
    Ok(())
}

