fn emit_all(package: &Utf8Path, out_dir: Option<&Utf8Path>) -> Result<()> {
    let project = MemSourceProject::load(package, LoadOptions)?;
    let extraction = project.extract(ExtractOptions)?;
    let report = project.validate(&extraction, ValidationOptions::strict())?;
    let emit_report = project.emit(
        &extraction,
        EmitOptions {
            output_dir: out_dir.map(Utf8Path::to_path_buf),
        },
    )?;
    let diagnostics_path = emit_report
        .output_dir
        .join(&project.package.outputs.diagnostics_json);
    diagnostics_json::write(&diagnostics_path, &report)?;
    if report.has_errors() {
        eprintln!("{}", report.render_human());
        std::process::exit(1);
    }
    println!("emitted {}", emit_report.output_dir);
    Ok(())
}

fn compare_yaml(package: &Utf8Path, baseline: &Utf8Path, out: &Utf8Path) -> Result<()> {
    let project = MemSourceProject::load(package, LoadOptions)?;
    let extraction = project.extract(ExtractOptions)?;
    let report: ComparisonReport = project.compare_yaml(&extraction, baseline)?;
    let body = serde_json::to_string_pretty(&report).map_err(|error| {
        MemsrcError::Message(format!("failed to serialize comparison: {error}"))
    })?;
    std::fs::write(out, body).map_err(|source| MemsrcError::io(out, source))
}

fn doctor(package: &Utf8Path) -> Result<()> {
    let project = MemSourceProject::load(package, LoadOptions)?;
    let files = project.discover()?;
    println!("package: {}", project.package.package_id);
    println!("root: {}", project.root_dir);
    println!("files: {}", files.len());
    println!("profile: {}", project.package.profile.profile_version);
    Ok(())
}

fn write_if_missing(path: &Utf8Path, body: &str) -> Result<()> {
    if path.exists() {
        return Ok(());
    }
    std::fs::write(path, body).map_err(|source| MemsrcError::io(path, source))
}

