    pub fn load(path: impl AsRef<Utf8Path>, _options: LoadOptions) -> Result<Self> {
        let package_path = path.as_ref().to_path_buf();
        let mut root_dir = package_path
            .parent()
            .ok_or_else(|| MemsrcError::Message("package path has no parent directory".into()))?
            .to_path_buf();
        if root_dir.as_str().is_empty() {
            root_dir = Utf8PathBuf::from(".");
        }
        let package = config::load_package(&package_path)?;
        Ok(Self {
            package,
            root_dir,
            package_path,
        })
    }

