        discover::discover_files(&self.root_dir, &self.package)
    }

    pub fn parse(&self, files: &[MemorySourceFile]) -> Result<Vec<ParsedMemoryFile>> {
        parse_files(&self.root_dir, files, &self.package.profile)
    }

    pub fn extract(&self, _options: ExtractOptions) -> Result<ExtractionSet> {
        let files = self.discover()?;
        let parsed = self.parse(&files)?;
        extract_records(&self.root_dir, &self.package, files, parsed)
    }

