use serde::{Deserialize, Serialize};

use crate::error::Result;
use crate::ir::{ExtractedMemoryRecord, Sensitivity};
use crate::parse::ExtractionSet;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RetrievalChunk {
    pub schema_version: String,
    pub chunk_id: String,
    pub memory_id: String,
    pub kind: String,
    pub text: String,
    pub tags: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub priority: Option<f32>,
    pub source_file: String,
    pub source_line: usize,
}

pub fn build_chunks(extraction: &ExtractionSet) -> Result<Vec<RetrievalChunk>> {
    let mut chunks = Vec::new();
    for record in &extraction.records {
        build_record_chunks(record, &mut chunks);
    }
    chunks.sort_by(|left, right| left.chunk_id.cmp(&right.chunk_id));
    Ok(chunks)
}

fn build_record_chunks(record: &ExtractedMemoryRecord, chunks: &mut Vec<RetrievalChunk>) {
    let allow_body = record.governance.sensitivity != Sensitivity::Secret
        || record.governance.redaction_notes.is_some();
    for field in &record.retrieval.embedding_fields {
        match field.as_str() {
            "title" => chunks.push(make_chunk(
                record,
                "title",
                &record.title,
                record.source.start_line,
            )),
            "summary" => chunks.push(make_chunk(
                record,
                "summary",
                &format!("{}: {}", record.title, record.summary),
                record.source.start_line,
            )),
            "body" if allow_body => {
                if let Some(body) = &record.body {
                    chunks.push(make_chunk(record, "body", body, record.source.start_line));
                }
            }
            "claims.text" => {
                for (index, claim) in record.claims.iter().enumerate() {
                    chunks.push(make_chunk(
                        record,
                        &format!("claim-{index}"),
                        &claim.text,
                        record.source.start_line,
                    ));
                }
            }
            "evidence.quote" => {
                for (index, evidence) in record.evidence.iter().enumerate() {
                    if let Some(quote) = &evidence.quote {
                        chunks.push(make_chunk(
                            record,
                            &format!("evidence-{index}"),
                            quote,
                            record.source.start_line,
                        ));
                    }
                }
            }
            _ => {}
        }
    }
}

fn make_chunk(
    record: &ExtractedMemoryRecord,
    kind: &str,
    text: &str,
    source_line: usize,
) -> RetrievalChunk {
    RetrievalChunk {
        schema_version: "memsrc.chunk.v0.1".into(),
        chunk_id: format!("chunk:{}:{kind}", record.id),
        memory_id: record.id.clone(),
        kind: kind.to_owned(),
        text: text.to_owned(),
        tags: record.retrieval.tags.clone(),
        priority: record.retrieval.priority,
        source_file: record.source.file.clone(),
        source_line,
    }
}

