use serde::{Deserialize, Serialize};

use crate::config::MemoryPackage;
use crate::error::Result;
use crate::parse::ExtractionSet;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MemoryGraph {
    pub schema_version: String,
    pub package_id: String,
    pub nodes: Vec<GraphNode>,
    pub edges: Vec<GraphEdge>,
    pub unresolved_edges: Vec<GraphEdge>,
    pub stats: GraphStats,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GraphNode {
    pub id: String,
    pub kind: String,
    pub title: String,
    pub status: String,
    pub file: String,
    pub export_name: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GraphEdge {
    pub from: String,
    pub rel: String,
    pub to: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub confidence: Option<f32>,
    pub source_file: String,
    pub source_line: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GraphStats {
    pub record_count: usize,
    pub edge_count: usize,
    pub claim_count: usize,
    pub unresolved_edge_count: usize,
}

pub fn build_graph(package: &MemoryPackage, extraction: &ExtractionSet) -> Result<MemoryGraph> {
    let ids = extraction
        .records
        .iter()
        .map(|record| record.id.clone())
        .collect::<std::collections::BTreeSet<_>>();

    let mut nodes = extraction
        .records
        .iter()
        .map(|record| GraphNode {
            id: record.id.clone(),
            kind: serde_json::to_value(&record.kind)
                .unwrap()
                .as_str()
                .unwrap()
                .to_owned(),
            title: record.title.clone(),
            status: serde_json::to_value(&record.status)
                .unwrap()
                .as_str()
                .unwrap()
                .to_owned(),
            file: record.source.file.clone(),
            export_name: record.symbols.record_symbol.clone(),
        })
        .collect::<Vec<_>>();
    nodes.sort_by(|left, right| left.id.cmp(&right.id));

    let mut edges = Vec::new();
    let mut unresolved_edges = Vec::new();
    for record in &extraction.records {
        for edge in &record.edges {
            let graph_edge = GraphEdge {
                from: edge.from.clone(),
                rel: serde_json::to_value(&edge.rel)
                    .unwrap()
                    .as_str()
                    .unwrap()
                    .to_owned(),
                to: edge.to.clone(),
                confidence: edge.confidence,
                source_file: edge.source.file.clone(),
                source_line: edge.source.start_line,
            };
            if ids.contains(&edge.to) {
                edges.push(graph_edge);
            } else {
                unresolved_edges.push(graph_edge);
            }
        }
    }
    edges.sort_by(|left, right| left.from.cmp(&right.from).then(left.to.cmp(&right.to)));
    unresolved_edges.sort_by(|left, right| left.from.cmp(&right.from).then(left.to.cmp(&right.to)));

    Ok(MemoryGraph {
        schema_version: "memsrc.graph.v0.1".into(),
        package_id: package.package_id.clone(),
        stats: GraphStats {
            record_count: extraction.records.len(),
            edge_count: edges.len(),
            claim_count: extraction
                .records
                .iter()
                .map(|record| record.claims.len())
                .sum(),
            unresolved_edge_count: unresolved_edges.len(),
        },
        nodes,
        edges,
        unresolved_edges,
    })
}

