use camino::{Utf8Path, Utf8PathBuf};
use globset::{Glob, GlobSetBuilder};
use ignore::WalkBuilder;

use crate::config::MemoryPackage;
use crate::discover::{MemorySourceFile, package::package_roots};
use crate::error::{MemsrcError, Result};

pub fn discover_files(
    root_dir: &Utf8Path,
    package: &MemoryPackage,
) -> Result<Vec<MemorySourceFile>> {
    let include_set = build_globset(&package.include)?;
    let exclude_set = build_globset(&package.exclude)?;
    let mut files = Vec::new();

    for package_root in package_roots(root_dir, package) {
        let mut builder = WalkBuilder::new(&package_root);
        builder
            .hidden(false)
            .git_ignore(false)
            .git_exclude(false)
            .parents(false);
        for result in builder.build() {
            let entry = match result {
                Ok(entry) => entry,
                Err(error) => {
                    return Err(MemsrcError::Message(format!(
                        "walk error under {}: {error}",
                        root_dir
                    )));
                }
            };
            if !entry
                .file_type()
                .map(|file_type| file_type.is_file())
                .unwrap_or(false)
            {
                continue;
            }
            let absolute_path = Utf8PathBuf::from_path_buf(entry.into_path())
                .map_err(|_| MemsrcError::Utf8Path("non-utf8 source path".into()))?;
            let relative_path = absolute_path
                .strip_prefix(root_dir)
                .map_err(|_| {
                    MemsrcError::Message(format!("source path escaped root: {absolute_path}"))
                })?
                .to_path_buf();
            let relative_string = relative_path.as_str();
            if !include_set.is_match(relative_string) || exclude_set.is_match(relative_string) {
                continue;
            }
            files.push(MemorySourceFile {
                absolute_path,
                relative_path,
            });
        }
    }

    files.sort_by(|left, right| left.relative_path.cmp(&right.relative_path));
    Ok(files)
}

fn build_globset(patterns: &[String]) -> Result<globset::GlobSet> {
    let mut builder = GlobSetBuilder::new();
    for pattern in patterns {
        let glob = Glob::new(pattern).map_err(|error| {
            MemsrcError::Message(format!("invalid glob pattern `{pattern}`: {error}"))
        })?;
        builder.add(glob);
    }
    builder
        .build()
        .map_err(|error| MemsrcError::Message(format!("invalid globset: {error}")))
}

