use std::collections::BTreeMap;

use crate::diagnostics::Diagnostic;
use crate::error::Result;
use crate::ir::SourceRef;

#[derive(Debug, Clone)]
pub struct ParsedExpr {
    pub source: SourceRef,
    pub kind: ParsedExprKind,
}

#[derive(Debug, Clone)]
pub enum ParsedExprKind {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Array(Vec<ParsedExpr>),
    Object(Vec<(String, ParsedExpr)>),
    Identifier(String),
}

#[derive(Debug, Clone)]
pub struct SourcedValue {
    pub source: SourceRef,
    pub value: EvaluatedValue,
    pub from_identifier: bool,
}

impl SourcedValue {
    pub fn new(source: SourceRef, value: EvaluatedValue) -> Self {
        Self {
            source,
            value,
            from_identifier: false,
        }
    }

    pub fn mark_identifier(mut self) -> Self {
        self.from_identifier = true;
        self
    }
}

#[derive(Debug, Clone)]
pub enum EvaluatedValue {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Array(Vec<SourcedValue>),
    Object(BTreeMap<String, SourcedValue>),
}

pub fn resolve_expr(
    expr: &ParsedExpr,
    resolver: &mut dyn FnMut(&str) -> Result<Option<SourcedValue>>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<SourcedValue> {
    let value = match &expr.kind {
        ParsedExprKind::String(value) => EvaluatedValue::String(value.clone()),
        ParsedExprKind::Number(value) => EvaluatedValue::Number(*value),
        ParsedExprKind::Bool(value) => EvaluatedValue::Bool(*value),
        ParsedExprKind::Null => EvaluatedValue::Null,
        ParsedExprKind::Array(items) => {
            let mut array = Vec::new();
            for item in items {
                array.push(resolve_expr(item, resolver, diagnostics)?);
            }
            EvaluatedValue::Array(array)
        }
        ParsedExprKind::Object(properties) => {
            let mut object = BTreeMap::new();
            for (key, value) in properties {
                object.insert(key.clone(), resolve_expr(value, resolver, diagnostics)?);
            }
            EvaluatedValue::Object(object)
        }
        ParsedExprKind::Identifier(identifier) => {
            if let Some(value) = resolver(identifier)? {
                return Ok(value);
            }
            diagnostics.push(Diagnostic::error(
                "PROFILE010",
                format!("identifier `{identifier}` could not be resolved"),
                expr.source.file.clone(),
                expr.source.start_line,
                expr.source.start_col,
            ));
            EvaluatedValue::Null
        }
    };
    Ok(SourcedValue::new(expr.source.clone(), value))
}

pub fn string_literal(source: SourceRef, value: impl Into<String>) -> ParsedExpr {
    ParsedExpr {
        source,
        kind: ParsedExprKind::String(value.into()),
    }
}

