fn required_value_enum<T>(
    file: &ParsedMemoryFile,
    object: &BTreeMap<String, SourcedValue>,
    key: &str,
    code: &str,
    diagnostics: &mut Vec<Diagnostic>,
    source: &SourcedValue,
    parser: fn(&str) -> Option<T>,
) -> Result<T> {
    let value = required_value_string(file, object, key, code, diagnostics, source)?;
    parser(&value).ok_or_else(|| MemsrcError::Message(format!("invalid `{key}` value `{value}`")))
}

fn as_string(value: &SourcedValue, field: &str) -> Result<String> {
    match &value.value {
        EvaluatedValue::String(item) => Ok(item.clone()),
        _ => Err(MemsrcError::Message(format!(
            "field `{field}` must be a string"
        ))),
    }
}

fn optional_number(object: &BTreeMap<String, SourcedValue>, key: &str) -> Result<Option<f64>> {
    object
        .get(key)
        .map(|value| match &value.value {
            EvaluatedValue::Number(item) => Ok(*item),
            _ => Err(MemsrcError::Message(format!(
                "field `{key}` must be a number"
            ))),
        })
        .transpose()
}

fn optional_bool(object: &BTreeMap<String, SourcedValue>, key: &str) -> Result<Option<bool>> {
    object
        .get(key)
        .map(|value| match &value.value {
            EvaluatedValue::Bool(item) => Ok(*item),
            _ => Err(MemsrcError::Message(format!(
                "field `{key}` must be a boolean"
            ))),
        })
        .transpose()
}

fn as_array<'a>(value: &'a SourcedValue, field: &str) -> Result<&'a [SourcedValue]> {
    match &value.value {
        EvaluatedValue::Array(items) => Ok(items.as_slice()),
        _ => Err(MemsrcError::Message(format!(
            "field `{field}` must be an array"
        ))),
    }
}

fn as_object<'a>(
    value: &'a SourcedValue,
    field: &str,
) -> Result<&'a BTreeMap<String, SourcedValue>> {
    match &value.value {
        EvaluatedValue::Object(items) => Ok(items),
        _ => Err(MemsrcError::Message(format!(
            "field `{field}` must be an object"
        ))),
    }
}

fn as_string_vec(value: &SourcedValue, field: &str) -> Result<Vec<String>> {
    let array = as_array(value, field)?;
    array.iter().map(|item| as_string(item, field)).collect()
}

fn optional_string_vec(object: &BTreeMap<String, SourcedValue>, key: &str) -> Result<Vec<String>> {
    object
        .get(key)
        .map(|value| as_string_vec(value, key))
        .transpose()
        .map(|items| items.unwrap_or_default())
}

fn parse_facets(value: &SourcedValue) -> Result<BTreeMap<String, Vec<String>>> {
    let object = as_object(value, "facets")?;
    let mut facets = BTreeMap::new();
    for (key, value) in object {
        let values = match &value.value {
            EvaluatedValue::String(item) => vec![item.clone()],
            EvaluatedValue::Array(_) => as_string_vec(value, key)?,
            _ => {
                return Err(MemsrcError::Message(format!(
                    "facet `{key}` must be a string or array of strings"
                )));
            }
        };
        facets.insert(key.clone(), values);
    }
    Ok(facets)
}

