use camino::Utf8Path;

use crate::error::{MemsrcError, Result};
use crate::parse::ExtractionSet;

pub fn write(path: &Utf8Path, extraction: &ExtractionSet) -> Result<()> {
    let mut lines = Vec::new();
    for record in &extraction.records {
        lines.push(serde_json::to_string(record).map_err(|error| {
            MemsrcError::Message(format!("failed to serialize record: {error}"))
        })?);
    }
    std::fs::write(path, lines.join("\n")).map_err(|source| MemsrcError::io(path, source))
}

