use camino::Utf8PathBuf;
use serde::Serialize;

use crate::diagnostics::ValidationReport;
use crate::error::{MemsrcError, Result};
use crate::index::{build_chunks, build_graph, build_symbols};
use crate::{EmitOptions, MemSourceProject, parse::ExtractionSet};

#[derive(Debug, Clone, Default)]
pub struct EmitReport {
    pub output_dir: Utf8PathBuf,
    pub written_files: Vec<Utf8PathBuf>,
}

pub fn emit_all(
    project: &MemSourceProject,
    extraction: &ExtractionSet,
    options: EmitOptions,
) -> Result<EmitReport> {
    let output_dir = project
        .package
        .outputs
        .dir_path(&project.root_dir, options.output_dir.as_deref());
    std::fs::create_dir_all(&output_dir).map_err(|source| MemsrcError::io(&output_dir, source))?;

    let records_path = output_dir.join(&project.package.outputs.records_jsonl);
    let graph_path = output_dir.join(&project.package.outputs.graph_json);
    let chunks_path = output_dir.join(&project.package.outputs.chunks_jsonl);
    let symbols_path = output_dir.join(&project.package.outputs.symbols_json);
    let diagnostics_path = output_dir.join(&project.package.outputs.diagnostics_json);
    let schema_path = output_dir.join(&project.package.outputs.schema_json);

    records_jsonl::write(&records_path, extraction)?;
    graph_json::write(&graph_path, &build_graph(&project.package, extraction)?)?;
    chunks_jsonl::write(&chunks_path, &build_chunks(extraction)?)?;
    symbols_json::write(&symbols_path, &build_symbols(extraction)?)?;
    diagnostics_json::write(
        &diagnostics_path,
        &ValidationReport {
            diagnostics: extraction.diagnostics.clone(),
            stats: Default::default(),
        },
    )?;
    schema_json::write(&schema_path, &project.package.outputs)?;

    Ok(EmitReport {
        output_dir,
        written_files: vec![
            records_path,
            graph_path,
            chunks_path,
            symbols_path,
            diagnostics_path,
            schema_path,
        ],
    })
}

pub(crate) fn write_json<T: Serialize>(path: &camino::Utf8Path, value: &T) -> Result<()> {
    let body = serde_json::to_string_pretty(value)
        .map_err(|error| MemsrcError::Message(format!("failed to serialize {}: {error}", path)))?;
    std::fs::write(path, body).map_err(|source| MemsrcError::io(path, source))
}

