fn normalize_record(
    file: &ParsedMemoryFile,
    profile_version: String,
    object: &BTreeMap<String, SourcedValue>,
    source: &SourceRef,
    record_symbol: String,
    id_symbol: Option<String>,
    imports: &[ParsedImport],
    consts: &IndexMap<String, ParsedConst>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<Option<ExtractedMemoryRecord>> {
    let schema_version = required_string(file, object, "schema_version", "RECORD008", diagnostics)?;
    let id = required_string(file, object, "id", "RECORD001", diagnostics)?;
    let kind = required_enum(file, object, "kind", "RECORD004", diagnostics, parse_kind)?;
    let title = required_string(file, object, "title", "RECORD006", diagnostics)?;
    let status = required_enum(
        file,
        object,
        "status",
        "RECORD005",
        diagnostics,
        parse_status,
    )?;
    let summary = required_string(file, object, "summary", "RECORD007", diagnostics)?;
    let body = optional_string(object, "body")?;
    let claims = parse_claims(file, object.get("claims"), diagnostics)?;
    let evidence = parse_evidence(file, object.get("evidence"), diagnostics)?;
    let edges = parse_edges(file, object.get("edges"), &id, diagnostics)?;
    let lifecycle = parse_lifecycle(file, object.get("lifecycle"), diagnostics)?;
    let retrieval = parse_retrieval(file, object.get("retrieval"), diagnostics)?;
    let governance = parse_governance(file, object.get("governance"), diagnostics)?;

    let mut hasher = Sha256::new();
    hasher.update(file.source_text.as_bytes());
    let source_hash = format!("{:x}", hasher.finalize());

    let local_consts = consts
        .values()
        .filter(|item| item.exported)
        .filter_map(|item| match &item.expr.kind {
            literal_eval::ParsedExprKind::String(value) => Some(ConstSymbol {
                name: item.name.clone(),
                value: value.clone(),
                source: item.source.clone(),
            }),
            _ => None,
        })
        .collect::<Vec<_>>();

    let symbols = SymbolRefSet {
        id_symbol,
        record_symbol,
        imports: imports
            .iter()
            .map(|item| ImportRef {
                local_name: item.local_name.clone(),
                imported_name: item.imported_name.clone(),
                source_path: item.source_path.clone(),
                type_only: item.type_only,
                resolved_file: item.resolved_file.clone(),
            })
            .collect(),
        local_consts,
    };

    Ok(Some(ExtractedMemoryRecord {
        schema_version,
        id,
        kind,
        title,
        status,
        summary,
        body,
        claims,
        edges,
        evidence,
        lifecycle,
        retrieval,
        governance,
        source: source.clone(),
        id_source: object.get("id").map(|value| value.source.clone()),
        title_source: object
            .get("title")
            .map(|value| value.source.clone())
            .unwrap_or_else(|| source.clone()),
        summary_source: object
            .get("summary")
            .map(|value| value.source.clone())
            .unwrap_or_else(|| source.clone()),
        body_source: object.get("body").map(|value| value.source.clone()),
        symbols,
        raw: RawExtractionInfo {
            source_hash,
            profile_version,
        },
    }))
}

fn required_string(
    file: &ParsedMemoryFile,
    object: &BTreeMap<String, SourcedValue>,
    key: &str,
    code: &str,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<String> {
    let Some(value) = object.get(key) else {
        diagnostics.push(Diagnostic::error(
            code,
            format!("`{key}` is required"),
            file.source_file.relative_path.as_str(),
            file.record_export
                .as_ref()
                .map(|item| item.source.start_line)
                .unwrap_or(1),
            file.record_export
                .as_ref()
                .map(|item| item.source.start_col)
                .unwrap_or(1),
        ));
        return Ok(String::new());
    };
    as_string(value, key)
}

fn optional_string(object: &BTreeMap<String, SourcedValue>, key: &str) -> Result<Option<String>> {
    object
        .get(key)
        .map(|value| as_string(value, key))
        .transpose()
}

fn required_enum<T>(
    file: &ParsedMemoryFile,
    object: &BTreeMap<String, SourcedValue>,
    key: &str,
    code: &str,
    diagnostics: &mut Vec<Diagnostic>,
    parser: fn(&str) -> Option<T>,
) -> Result<T> {
    let raw = required_string(file, object, key, code, diagnostics)?;
    parser(&raw).ok_or_else(|| MemsrcError::Message(format!("invalid `{key}` value `{raw}`")))
}

fn parse_claims(
    file: &ParsedMemoryFile,
    value: Option<&SourcedValue>,
    diagnostics: &mut Vec<Diagnostic>,
