    let array = as_array(value, "claims")?;
    let mut claims = Vec::new();
    for claim in array {
        let object = as_object(claim, "claim")?;
        claims.push(MemoryClaim {
            id: required_value_string(file, object, "id", "CLAIM001", diagnostics, claim)?,
            text: required_value_string(file, object, "text", "CLAIM002", diagnostics, claim)?,
            stance: required_value_enum(
                file,
                object,
                "stance",
                "CLAIM005",
                diagnostics,
                claim,
                parse_claim_stance,
            )?,
            confidence: optional_number(object, "confidence")?.unwrap_or_default() as f32,
            basis: required_value_enum(
                file,
                object,
                "basis",
                "CLAIM004",
                diagnostics,
                claim,
                parse_claim_basis,
            )?,
            evidence_refs: optional_string_vec(object, "evidence_refs")?,
            qualifiers: optional_string_vec(object, "qualifiers")?,
            valid_from: optional_string(object, "valid_from")?,
            valid_until: optional_string(object, "valid_until")?,
        });
    }
    Ok(claims)
}

