fn parse_facets(value: &SourcedValue) -> Result<BTreeMap<String, Vec<String>>> {
    let object = as_object(value, "facets")?;
    let mut facets = BTreeMap::new();
    for (key, value) in object {
        let values = match &value.value {
            EvaluatedValue::String(item) => vec![item.clone()],
            EvaluatedValue::Array(_) => as_string_vec(value, key)?,
            _ => {
                return Err(MemsrcError::Message(format!(
                    "facet `{key}` must be a string or array of strings"
                )));
            }
        };
        facets.insert(key.clone(), values);
    }
    Ok(facets)
}

pub(crate) fn parse_kind(value: &str) -> Option<MemoryKind> {
    Some(match value {
        "entity" => MemoryKind::Entity,
        "project" => MemoryKind::Project,
        "artifact" => MemoryKind::Artifact,
        "concept" => MemoryKind::Concept,
        "episode" => MemoryKind::Episode,
        "fact" => MemoryKind::Fact,
        "belief" => MemoryKind::Belief,
        "preference" => MemoryKind::Preference,
        "decision" => MemoryKind::Decision,
        "procedure" => MemoryKind::Procedure,
        "constraint" => MemoryKind::Constraint,
        "task" => MemoryKind::Task,
        "question" => MemoryKind::Question,
        "summary" => MemoryKind::Summary,
        _ => return None,
    })
}

pub(crate) fn parse_status(value: &str) -> Option<MemoryStatus> {
    Some(match value {
        "draft" => MemoryStatus::Draft,
        "active" => MemoryStatus::Active,
        "stale" => MemoryStatus::Stale,
        "superseded" => MemoryStatus::Superseded,
        "retracted" => MemoryStatus::Retracted,
        "archived" => MemoryStatus::Archived,
        _ => return None,
    })
}

pub(crate) fn parse_claim_basis(value: &str) -> Option<ClaimBasis> {
    Some(match value {
        "user_stated" => ClaimBasis::UserStated,
        "observed" => ClaimBasis::Observed,
        "inferred" => ClaimBasis::Inferred,
        "reasoned" => ClaimBasis::Reasoned,
        "derived" => ClaimBasis::Derived,
        "external_source" => ClaimBasis::ExternalSource,
        "system_generated" => ClaimBasis::SystemGenerated,
        _ => return None,
    })
}

pub(crate) fn parse_claim_stance(value: &str) -> Option<ClaimStance> {
    Some(match value {
        "asserts" => ClaimStance::Asserts,
        "denies" => ClaimStance::Denies,
        "qualifies" => ClaimStance::Qualifies,
        "questions" => ClaimStance::Questions,
        _ => return None,
    })
}

pub(crate) fn parse_edge_rel(value: &str) -> Option<EdgeRel> {
    Some(match value {
        "about" => EdgeRel::About,
        "mentions" => EdgeRel::Mentions,
        "related_to" => EdgeRel::RelatedTo,
        "part_of" => EdgeRel::PartOf,
        "instance_of" => EdgeRel::InstanceOf,
        "depends_on" => EdgeRel::DependsOn,
        "supports" => EdgeRel::Supports,
        "contradicts" => EdgeRel::Contradicts,
        "conflicts_with" => EdgeRel::ConflictsWith,
        "supersedes" => EdgeRel::Supersedes,
        "refines" => EdgeRel::Refines,
        "derived_from" => EdgeRel::DerivedFrom,
        "decided_by" => EdgeRel::DecidedBy,
        "implements" => EdgeRel::Implements,
        "owned_by" => EdgeRel::OwnedBy,
        "used_for" => EdgeRel::UsedFor,
        "blocks" => EdgeRel::Blocks,
        "follows" => EdgeRel::Follows,
        "caused_by" => EdgeRel::CausedBy,
        _ => return None,
    })
}

fn parse_evidence_kind(value: &str) -> Option<EvidenceKind> {
    Some(match value {
        "conversation" => EvidenceKind::Conversation,
        "file" => EvidenceKind::File,
        "git_commit" => EvidenceKind::GitCommit,
        "url" => EvidenceKind::Url,
        "email" => EvidenceKind::Email,
        "manual_note" => EvidenceKind::ManualNote,
        "system_event" => EvidenceKind::SystemEvent,
        _ => return None,
    })
}

