fn id_matches_namespace(value: &str) -> bool {
    let dynamic = [
        "entity:user:",
        "entity:org:",
        "entity:person:",
        "entity:tool:",
        "project:",
        "artifact:",
        "concept:",
        "episode:",
        "decision:",
        "procedure:",
        "constraint:",
        "summary:",
        "mem:",
    ];
    dynamic.iter().any(|prefix| value.starts_with(prefix))
}

fn is_iso_date(value: &str) -> bool {
    NaiveDate::parse_from_str(value, "%Y-%m-%d").is_ok()
}

