pub fn load_yaml_baseline(baseline_dir: &Utf8Path) -> Result<Vec<ExtractedMemoryRecord>> {
    let mut paths = Vec::new();
    collect_yaml_files(baseline_dir, &mut paths)?;
    paths.sort();
    let mut records = Vec::new();
    for path in paths {
        let content =
            std::fs::read_to_string(&path).map_err(|source| MemsrcError::io(&path, source))?;
        let yaml: YamlRecord =
            serde_yaml::from_str(&content).map_err(|source| MemsrcError::yaml(&path, source))?;
        let relative = path
            .strip_prefix(baseline_dir)
            .map_err(|_| MemsrcError::Message(format!("baseline path escaped root: {path}")))?
            .to_path_buf();
        records.push(ExtractedMemoryRecord {
            schema_version: yaml.schema_version,
            id: yaml.id.clone(),
            kind: parse_kind(&yaml.kind)?,
            title: yaml.title,
            status: parse_status(&yaml.status)?,
            summary: yaml.summary,
            body: yaml.body,
            claims: yaml
                .claims
                .into_iter()
                .map(|claim| {
                    Ok(MemoryClaim {
                        id: claim.id,
                        text: claim.text,
                        stance: parse_claim_stance(&claim.stance)?,
                        confidence: claim.confidence,
                        basis: parse_claim_basis(&claim.basis)?,
                        evidence_refs: Vec::new(),
                        qualifiers: Vec::new(),
                        valid_from: None,
                        valid_until: None,
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            edges: yaml
                .edges
                .into_iter()
                .map(|edge| {
                    Ok(MemoryEdge {
                        from: yaml.id.clone(),
                        rel: parse_edge_rel(&edge.rel)?,
                        to: edge.to,
                        confidence: None,
                        strength: None,
                        note: None,
                        evidence_refs: Vec::new(),
                        source: SourceRef {
                            file: relative.as_str().to_owned(),
                            export_name: String::new(),
                            start_line: 1,
                            start_col: 1,
                            end_line: 1,
                            end_col: 1,
                            start_byte: 0,
                            end_byte: 0,
                        },
                        symbolic_target: false,
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            evidence: Vec::new(),
            lifecycle: MemoryLifecycle {
                created_at: yaml.lifecycle.created_at,
                updated_at: None,
                valid_from: None,
                valid_until: None,
                supersedes: Vec::new(),
                superseded_by: Vec::new(),
                retraction: None,
            },
            retrieval: RetrievalSpec {
                tags: yaml.retrieval.tags,
                embedding_fields: yaml.retrieval.embedding_fields,
                keywords: Vec::new(),
                facets: BTreeMap::new(),
                priority: None,
                pin: false,
                decay: None,
            },
            governance: GovernanceSpec {
                sensitivity: parse_sensitivity(&yaml.governance.sensitivity)?,
                owner: None,
                retention: None,
