                record_symbol: String::new(),
                imports: Vec::new(),
                local_consts: Vec::new(),
            },
            raw: RawExtractionInfo {
                source_hash: String::new(),
                profile_version: "yaml-baseline.v0.1".into(),
            },
        });
    }
    Ok(records)
}

fn collect_yaml_files(root: &Utf8Path, out: &mut Vec<Utf8PathBuf>) -> Result<()> {
    for entry in std::fs::read_dir(root).map_err(|source| MemsrcError::io(root, source))? {
        let entry = entry.map_err(|source| MemsrcError::io(root, source))?;
        let path = Utf8PathBuf::from_path_buf(entry.path())
            .map_err(|_| MemsrcError::Utf8Path("non-utf8 yaml path".into()))?;
        if path.is_dir() {
            collect_yaml_files(&path, out)?;
        } else if matches!(path.extension(), Some("yaml" | "yml")) {
            out.push(path);
        }
    }
    Ok(())
}

