pub fn load_yaml_baseline(baseline_dir: &Utf8Path) -> Result<Vec<ExtractedMemoryRecord>> {
    let mut paths = Vec::new();
    collect_yaml_files(baseline_dir, &mut paths)?;
    paths.sort();
    let mut records = Vec::new();
    for path in paths {
        let content =
            std::fs::read_to_string(&path).map_err(|source| MemsrcError::io(&path, source))?;
        let yaml: YamlRecord =
            serde_yaml::from_str(&content).map_err(|source| MemsrcError::yaml(&path, source))?;
        let relative = path
            .strip_prefix(baseline_dir)
            .map_err(|_| MemsrcError::Message(format!("baseline path escaped root: {path}")))?
            .to_path_buf();
        let source = placeholder_source(&relative, 1);
        let title_source = placeholder_source(&relative, 2);
        let summary_source = placeholder_source(&relative, 3);
        let body_source = yaml
            .body
            .as_ref()
            .map(|_| placeholder_source(&relative, 4));
        records.push(ExtractedMemoryRecord {
            schema_version: yaml.schema_version,
            id: yaml.id.clone(),
            kind: parse_kind(&yaml.kind)?,
            title: yaml.title,
            status: parse_status(&yaml.status)?,
            summary: yaml.summary,
            body: yaml.body,
            claims: yaml
                .claims
                .into_iter()
                .enumerate()
                .map(|(index, claim)| {
                    Ok(MemoryClaim {
                        id: claim.id,
                        text: claim.text,
                        stance: parse_claim_stance(&claim.stance)?,
                        confidence: claim.confidence,
                        basis: parse_claim_basis(&claim.basis)?,
                        evidence_refs: claim.evidence_refs,
                        qualifiers: claim.qualifiers,
                        valid_from: claim.valid_from,
                        valid_until: claim.valid_until,
                        source: placeholder_source(&relative, 20 + index),
                        text_source: placeholder_source(&relative, 20 + index),
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            edges: yaml
                .edges
                .into_iter()
                .enumerate()
                .map(|(index, edge)| {
                    Ok(MemoryEdge {
                        from: yaml.id.clone(),
                        rel: parse_edge_rel(&edge.rel)?,
                        to: edge.to,
                        confidence: edge.confidence,
                        strength: edge.strength,
                        note: edge.note,
                        evidence_refs: edge.evidence_refs,
                        source: placeholder_source(&relative, 40 + index),
                        symbolic_target: false,
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            evidence: yaml
                .evidence
                .into_iter()
                .enumerate()
                .map(|(index, evidence)| {
                    Ok(EvidenceRef {
                        id: evidence.id,
                        kind: parse_evidence_kind(&evidence.kind)?,
                        title: evidence.title,
                        locator: evidence.locator,
                        captured_at: evidence.captured_at,
                        quote_source: evidence
                            .quote
                            .as_ref()
                            .map(|_| placeholder_source(&relative, 60 + index)),
                        quote: evidence.quote,
                        hash: evidence.hash,
                        source: placeholder_source(&relative, 60 + index),
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            lifecycle: MemoryLifecycle {
                created_at: yaml.lifecycle.created_at,
                updated_at: yaml.lifecycle.updated_at,
                valid_from: yaml.lifecycle.valid_from,
                valid_until: yaml.lifecycle.valid_until,
                supersedes: yaml.lifecycle.supersedes,
                superseded_by: yaml.lifecycle.superseded_by,
                retraction: yaml.lifecycle.retraction.map(|retraction| Retraction {
                    retracted_at: retraction.retracted_at,
                    reason: retraction.reason,
                    replaced_by: retraction.replaced_by,
                }),
            },
            retrieval: RetrievalSpec {
                tags: yaml.retrieval.tags,
                embedding_fields: yaml.retrieval.embedding_fields,
                keywords: yaml.retrieval.keywords,
                facets: yaml
                    .retrieval
                    .facets
                    .into_iter()
                    .map(|(key, value)| {
                        let values = match value {
                            YamlFacetValue::Single(item) => vec![item],
                            YamlFacetValue::Multi(items) => items,
                        };
                        (key, values)
                    })
                    .collect(),
                priority: yaml.retrieval.priority,
                pin: yaml.retrieval.pin,
                decay: yaml.retrieval.decay,
            },
            governance: GovernanceSpec {
                sensitivity: parse_sensitivity(&yaml.governance.sensitivity)?,
                owner: yaml.governance.owner,
                retention: yaml.governance.retention,
                review_after: yaml.governance.review_after,
                redaction_notes: yaml.governance.redaction_notes,
            },
            source: source.clone(),
            id_source: Some(source.clone()),
            title_source,
            summary_source,
            body_source,
            symbols: SymbolRefSet {
                id_symbol: None,
                record_symbol: String::new(),
                imports: Vec::new(),
                local_consts: Vec::new(),
            },
            raw: RawExtractionInfo {
                source_hash: String::new(),
                profile_version: "yaml-baseline.v0.2".into(),
            },
        });
    }
    Ok(records)
}

fn collect_yaml_files(root: &Utf8Path, out: &mut Vec<Utf8PathBuf>) -> Result<()> {
    for entry in std::fs::read_dir(root).map_err(|source| MemsrcError::io(root, source))? {
        let entry = entry.map_err(|source| MemsrcError::io(root, source))?;
        let path = Utf8PathBuf::from_path_buf(entry.path())
            .map_err(|_| MemsrcError::Utf8Path("non-utf8 yaml path".into()))?;
        if path.is_dir() {
            collect_yaml_files(&path, out)?;
        } else if matches!(path.extension(), Some("yaml" | "yml")) {
            out.push(path);
        }
    }
    Ok(())
}

fn placeholder_source(relative: &Utf8Path, line: usize) -> SourceRef {
    SourceRef {
        file: relative.as_str().to_owned(),
        export_name: String::new(),
        start_line: line,
        start_col: 1,
        end_line: line,
        end_col: 1,
        start_byte: 0,
        end_byte: 0,
    }
}

