            .map(|chunk| normalize_chunk(&chunk))
            .collect(),
    );
    let graph_parity = {
        let source_graph = build_graph(package, extraction)?;
        let baseline_graph = build_graph(package, &baseline_extraction)?;
        let left = source_graph
            .nodes
            .into_iter()
            .map(|node| format!("node:{}:{}:{}", node.id, node.kind, node.status))
            .chain(
                source_graph
                    .edges
                    .into_iter()
                    .map(|edge| format!("edge:{}:{}:{}", edge.from, edge.rel, edge.to)),
            )
            .collect::<BTreeSet<_>>();
        let right = baseline_graph
            .nodes
            .into_iter()
            .map(|node| format!("node:{}:{}:{}", node.id, node.kind, node.status))
            .chain(
                baseline_graph
                    .edges
                    .into_iter()
                    .map(|edge| format!("edge:{}:{}:{}", edge.from, edge.rel, edge.to)),
            )
            .collect::<BTreeSet<_>>();
        set_parity(left, right)
    };

    let source_validation =
        validate_extraction(package, extraction, ValidationOptions { strict: true })?;
    let baseline_validation =
        validate_extraction(package, &baseline_extraction, ValidationOptions { strict: true })?;

    Ok(ComparisonReport {
        schema_version: "memsrc.compare.v0.2".into(),
        source_record_count: extraction.records.len(),
        baseline_record_count: baseline.len(),
        matching_ids,
        missing_in_source,
        missing_in_baseline,
        field_parity: score::parity_score(field_matches, field_total),
        claim_parity,
        edge_parity,
        lifecycle_parity: score::parity_score(lifecycle_matches, source_records.len().min(baseline_records.len())),
        retrieval_parity: score::parity_score(retrieval_matches, source_records.len().min(baseline_records.len())),
        governance_parity: score::parity_score(governance_matches, source_records.len().min(baseline_records.len())),
        chunk_parity,
        graph_parity,
        diagnostic_delta: diff_diagnostic_counts(
            &source_validation.diagnostics,
            &baseline_validation.diagnostics,
        ),
        mismatched_sections,
    })
}

fn collect_claims(
    extraction: &ExtractionSet,
    other: &BTreeMap<String, &ExtractedMemoryRecord>,
) -> BTreeSet<String> {
    extraction
        .records
        .iter()
        .filter(|record| other.contains_key(&record.id))
        .flat_map(|record| {
            record
                .claims
                .iter()
                .map(|claim| format!("{}::{}", record.id, normalize_claim(claim)))
        })
        .collect()
}

fn collect_edges(
    extraction: &ExtractionSet,
    other: &BTreeMap<String, &ExtractedMemoryRecord>,
) -> BTreeSet<String> {
    extraction
        .records
        .iter()
        .filter(|record| other.contains_key(&record.id))
        .flat_map(|record| {
            record
                .edges
                .iter()
                .map(|edge| format!("{}::{}", record.id, normalize_edge(edge)))
        })
        .collect()
}

fn normalize_claim(claim: &MemoryClaim) -> String {
    serde_json::to_string(&json!({
        "id": claim.id,
        "text": claim.text,
        "stance": claim.stance,
        "confidence": claim.confidence,
        "basis": claim.basis,
        "evidence_refs": claim.evidence_refs,
        "qualifiers": claim.qualifiers,
        "valid_from": claim.valid_from,
        "valid_until": claim.valid_until,
    }))
    .expect("claim json")
}

fn normalize_edge(edge: &MemoryEdge) -> String {
    serde_json::to_string(&json!({
        "from": edge.from,
        "rel": edge.rel,
        "to": edge.to,
        "confidence": edge.confidence,
        "strength": edge.strength,
        "note": edge.note,
        "evidence_refs": edge.evidence_refs,
    }))
    .expect("edge json")
}

fn normalize_lifecycle(lifecycle: &MemoryLifecycle) -> String {
    serde_json::to_string(lifecycle).expect("lifecycle json")
}

fn normalize_retrieval(retrieval: &RetrievalSpec) -> String {
    serde_json::to_string(retrieval).expect("retrieval json")
}

fn normalize_governance(governance: &GovernanceSpec) -> String {
    serde_json::to_string(governance).expect("governance json")
}

fn normalize_chunk(chunk: &RetrievalChunk) -> String {
    serde_json::to_string(&json!({
        "chunk_id": chunk.chunk_id,
        "memory_id": chunk.memory_id,
        "kind": chunk.kind,
        "text": chunk.text,
        "tags": chunk.tags,
        "priority": chunk.priority,
    }))
    .expect("chunk json")
}

fn set_parity(left: BTreeSet<String>, right: BTreeSet<String>) -> f32 {
    let matches = left.intersection(&right).count();
    let total = left.union(&right).count();
    score::parity_score(matches, total)
}

fn diff_diagnostic_counts(
    source: &[Diagnostic],
    baseline: &[Diagnostic],
) -> BTreeMap<String, i32> {
    let mut counts = BTreeMap::new();
    for diagnostic in source {
        *counts.entry(diagnostic.code.clone()).or_insert(0) += 1;
    }
    for diagnostic in baseline {
        *counts.entry(diagnostic.code.clone()).or_insert(0) -= 1;
    }
    counts.retain(|_, delta| *delta != 0);
    counts
}
