use camino::Utf8Path;

use crate::error::{MemsrcError, Result};
use crate::index::RetrievalChunk;

pub fn write(path: &Utf8Path, chunks: &[RetrievalChunk]) -> Result<()> {
    let body = chunks
        .iter()
        .map(|chunk| serde_json::to_string(chunk))
        .collect::<std::result::Result<Vec<_>, _>>()
        .map_err(|error| MemsrcError::Message(format!("failed to serialize chunk: {error}")))?
        .join("\n");
    std::fs::write(path, body).map_err(|source| MemsrcError::io(path, source))
}

