use camino::Utf8Path;

pub fn resolve_relative_import(file_path: &Utf8Path, source_path: &str) -> Option<String> {
    let parent = file_path.parent()?;
    let joined = parent.join(source_path);
    let joined_string = normalize_path(&joined.as_str().replace('\\', "/"));
    let candidates = if joined_string.ends_with(".mem") {
        vec![format!("{joined_string}.ts")]
    } else if joined_string.ends_with(".mem.ts") {
        vec![joined_string]
    } else if joined.extension().is_some() {
        vec![joined_string]
    } else {
        vec![
            joined.with_extension("ts").as_str().replace('\\', "/"),
            format!("{joined_string}.ts"),
        ]
    };

    candidates
        .into_iter()
        .find(|candidate| candidate.ends_with(".ts"))
}

fn normalize_path(path: &str) -> String {
    let mut stack = Vec::new();
    for segment in path.split('/') {
        match segment {
            "" | "." => {}
            ".." => {
                stack.pop();
            }
            value => stack.push(value),
        }
    }
    stack.join("/")
}

