use tree_sitter::{Language, Parser, Tree};

use crate::error::{MemsrcError, Result};

pub fn parser() -> Result<Parser> {
    let mut parser = Parser::new();
    parser.set_language(&language()).map_err(|error| {
        MemsrcError::Message(format!("failed to load TypeScript grammar: {error}"))
    })?;
    Ok(parser)
}

pub fn parse(source: &str) -> Result<Tree> {
    let mut parser = parser()?;
    parser
        .parse(source, None)
        .ok_or_else(|| MemsrcError::Message("tree-sitter failed to parse TypeScript source".into()))
}

pub fn language() -> Language {
    tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into()
}

